import sys,json,pathlib,hashlib,datetime
ROOT=pathlib.Path(__file__).resolve().parents[3]
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
def qhash(q):return digest({k:v for k,v in q.items() if k not in ('status','reviewIds')})
p=pathlib.Path(sys.argv[1]);audit=json.load(open(p));exclude=set(sys.argv[2:]);m=json.load(open(ROOT/'data/question-visuals/manifest.json'));rs={r['questionId']:r for r in m['records']}; qs={q['id']:q for f in (ROOT/'data/question-batches').glob('*.json') for q in json.load(open(f))['questions']};out=ROOT/f"data/question-visuals/reviews/{audit['lecture']}-self-contained-early-review.json"; reviews=json.load(open(out)) if out.exists() else [];by={r['questionId']:r for r in reviews};good=[];stale=[]
for item in audit['records']:
 id=item['questionId'];r=rs[id];q=qs[id]
 if id in exclude:continue
 if item['visualSha256']!=digest(r) or item['questionSha256']!=qhash(q) or r['dependencyStatus']!='self_contained':stale.append(id);continue
 assert not r['assetIds']
 by[id]={'id':f"QVR-{id}-v{r['version']}-early-input",'visualId':r['id'],'visualVersion':r['version'],'visualSha256':digest(r),'reviewerId':'review_early_question_inputs','decision':'verified','questionId':id,'questionVersion':q['version'],'questionSha256':qhash(q),'sourceVersions':{ref['sourceId']:ref['sourceSha256'] for ref in r['sourceRefs']},'assetHashes':{},'assetMetadataHashes':{},'reviewedAssetIds':[],'displayRole':'question_input','checks':{c:True for c in ('inventoryCompleteness','requiredInputFidelity','legibility','noAnswerLeak','sourceLinkage')},'reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reasoning':'Independently read this exact question’s complete stem, every option and every explicit assumption. The visible text supplies the necessary concrete inputs, or asks source-attributed factual/conceptual recall rather than computation or interpretation of an omitted concrete visual instance. No additional question-input asset is required.','scope':'Input-completeness classification only; not a new answer-correctness review. No source crop is attached or approved. Crop fidelity, legibility and answer-leak checks are nonapplicable because assetIds is empty. Both local PDF SHA-256 values were independently recomputed and matched the manifest source versions.','findings':[]};good.append(id)
out.write_text(json.dumps(sorted(by.values(),key=lambda r:r['questionId']),ensure_ascii=False,indent=2)+'\n');audit.update({'readStatus':'adjudicated','acceptedIds':good,'excludedForMissingDependencyIds':sorted(exclude),'changedDuringReviewIds':stale});p.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Accepted',len(good),'excluded',exclude,'changed',stale,'lecture review total',len(by))
